import java.time.LocalDate;

public class Main {
    public static void main(String[] args) {
        int[] years = {2000, 1900, 2024, 2023, 2100};
        for (int y : years) {
            System.out.println(y + " はうるう年か: " + LocalDate.of(y, 1, 1).isLeapYear());
        }

        try {
            LocalDate.of(2023, 2, 29);
        } catch (Exception e) {
            System.out.println("2023-02-29 → " + e.getClass().getSimpleName());
        }

        try {
            LocalDate.of(2024, 13, 1);
        } catch (Exception e) {
            System.out.println("13月 → " + e.getClass().getSimpleName());
        }
    }
}

