import java.time.Duration;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int y1 = sc.nextInt();
        int m1 = sc.nextInt();
        int d1 = sc.nextInt();
        int y2 = sc.nextInt();
        int m2 = sc.nextInt();
        int d2 = sc.nextInt();
        int h1 = sc.nextInt();
        int mi1 = sc.nextInt();
        int h2 = sc.nextInt();
        int mi2 = sc.nextInt();

        LocalDate from = LocalDate.of(y1, m1, d1);
        LocalDate to = LocalDate.of(y2, m2, d2);

        System.out.println("月数 " + ChronoUnit.MONTHS.between(from, to));
        System.out.println("年数 " + ChronoUnit.YEARS.between(from, to));
        System.out.println("逆 " + ChronoUnit.DAYS.between(to, from));

        LocalDateTime start = LocalDateTime.of(y1, m1, d1, h1, mi1);
        LocalDateTime end = LocalDateTime.of(y1, m1, d1, h2, mi2);
        Duration duration = Duration.between(start, end);
        System.out.println("時間 " + duration.toHours());
        System.out.println("分 " + duration.toMinutes());

        try {
            Duration.between(from, to);
            System.out.println("だめ 例外なし");
        } catch (Exception e) {
            System.out.println("だめ 例外");
        }
    }
}

