import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String ds = sc.next();
        String ts = sc.next();

        DateTimeFormatter reader = DateTimeFormatter.ofPattern("yyyy/MM/dd HH:mm");
        LocalDateTime dt = LocalDateTime.parse(ds + " " + ts, reader);

        System.out.println("読んだ " + dt);
        System.out.println("24時間 " + dt.format(DateTimeFormatter.ofPattern("HH")));
        System.out.println("12時間 " + dt.format(DateTimeFormatter.ofPattern("hh")));
        System.out.println("秒まで " + dt.format(DateTimeFormatter.ofPattern("HH:mm:ss")));
        System.out.println("文字 " + dt.format(DateTimeFormatter.ofPattern("yyyy'y'M'm'd'd'")));
    }
}

